#!/usr/bin/env node
// aquila CLI (Node ≥ 22, no dependencies), shared by aquila-ai (NestJS), aquila-react-ai and aquila-next-ai:
// generated by aquila-core, the package identity comes from ./profile.mjs. Runs from the root of a project
// that has the package installed as a devDependency. The method (rules, skills, roles) is copied to the
// versioned .aquila/:
//   npx <package> init    → detects the project, creates docs/ai and docs/*, generates adapters, sets hooks
//   npx <package> sync    → (re)generates the per-tool adapters from docs/ai/aquila.json
//   npx <package> check   → links, budgets, instructions, adapters in sync (fails in CI)
//   npx <package> doctor  → installation diagnostics (never fails)
//   npx <package> gate <pre-commit|pre-push|ci> → runs the aquila.json gates, prints only failures
// AQUILA_ROOT overrides the project root (tests); otherwise it is the current directory.
import { execFileSync, spawnSync } from 'node:child_process';
import {
  chmodSync,
  cpSync,
  existsSync,
  lstatSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  readlinkSync,
  realpathSync,
  rmSync,
  statSync,
  rmdirSync,
  unlinkSync,
  writeFileSync,
} from 'node:fs';
import { basename, dirname, join, posix as posixPath, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { checkConfig, validate } from './config-validation.mjs';
import { globToRegex } from './glob.mjs';
import {
  docWarnings,
  hookIssues,
  inspectDocuments,
  readinessIssues,
  TEMPLATE_MARKS,
} from './checks.mjs';
import { PROFILE } from './profile.mjs';
import {
  dispatcherFiles,
  DISPATCH_DIR,
  hooksPathKind,
  indexModeIssues,
  isDispatcher,
  layout,
  PHASES as HOOK_PHASES,
  readRegistry,
  register,
  REGISTRY,
  stageExecutable,
  writeDispatcher,
} from './repo.mjs';
import {
  coverageRunsTests,
  defaultConfig,
  dependencyMajor,
  detectStack,
  loadPreset,
  workspaces as detectWorkspaces,
} from './stack.mjs';
import {
  addLintGate,
  LINT_LEVELS,
  lint as runLint,
  lintPeerIssues,
  lintRules,
  lintSummary,
  missingLintPlugins,
  missingTool,
} from './lint.mjs';

/** npm name of this package (aquila-ai, aquila-react-ai, aquila-next-ai). */
const NAME = PROFILE.pkg;
const SELF = fileURLToPath(import.meta.url);
const PKG = resolve(dirname(SELF), '..');
const ROOT = resolve(process.env.AQUILA_ROOT ?? process.cwd());
const CONFIG = 'docs/ai/aquila.json';
// The dev's, not the team's (their plan's token limit): outside git, like the local adapters.
const LOCAL = 'docs/ai/aquila.local.json';
const MARK = `generated by ${NAME} (npx ${NAME} sync) — do not edit`;
// The method copied into the project: versioned, readable by cloud agents, refreshed by sync.
const METHOD = '.aquila';
const METHOD_ITEMS = [
  'AGENTS.md',
  'core',
  'skills',
  'agents',
  'adapters',
  'schema',
  'hooks',
  '.claude-plugin',
  'lint/rules.json',
];
// Where the project sits in its git repository: hooks, CI and git exclude are anchored at the repo root.
const REPO = layout(ROOT);
/** A repo-root path as seen from the project (e.g. "../.github/workflows/x.yml" from backend/). */
const atTop = (path) => posix(relative(ROOT, join(REPO.top, path)));
const ROUTERS = ['AGENTS.md', 'CLAUDE.md', '.github/copilot-instructions.md'];
// Per-folder rules live in .github/instructions/: Copilot reads them natively on every surface
// (VS Code, PR review, coding agent); the other agents open the folder's file through the map.
const INSTRUCTIONS = '.github/instructions';
const DEFAULT_BUDGETS = {
  'AGENTS.md': 3500,
  '.github/copilot-instructions.md': 8000,
  'docs/ai/CONTEXT.md': 14500,
  'docs/ai/golden.md': 6000,
  [`${INSTRUCTIONS}/*.instructions.md`]: 2500,
  'docs/ai/skills/*/SKILL.md': 10000,
};

/** Paths where environment variables may be read (AQ-CFG-01), by default (stacks/<preset>.json). */
export const DEFAULT_CONFIG_PATHS = loadPreset().configPaths;
const p = (...parts) => join(ROOT, ...parts);
// A BOM (Windows PowerShell 5 writes one) is not content.
const read = (file) => readFileSync(p(file), 'utf8').replace(/^\uFEFF/, '');
const readJson = (file) => JSON.parse(read(file));
const posix = (path) => path.split('\\').join('/');
const escapeRe = (text) => text.replaceAll(/[.*+?^${}()|[\]\\]/g, '\\$&');
const log =(ok, msg) => console.log(`${ok ? '✓' : '✗'} ${msg}`);
export const version = () =>
  JSON.parse(readFileSync(join(PKG, 'package.json'), 'utf8')).version;

function git(...args) {
  try {
    return execFileSync('git', args, {
      cwd: ROOT,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
  } catch {
    return '';
  }
}

function walk(dir, pick = () => true) {
  const full = p(dir);
  if (!existsSync(full) || !statSync(full).isDirectory()) return [];
  return readdirSync(full).flatMap((name) => {
    const rel = posix(join(dir, name));
    if (['node_modules', '.git', 'dist', 'coverage'].includes(name)) return [];
    if (lstatSync(p(rel)).isSymbolicLink()) return [];
    return statSync(p(rel)).isDirectory() ? walk(rel, pick) : pick(rel) ? [rel] : [];
  });
}

/** Simple YAML frontmatter: `key: value` and `>-`/`>`/`|` blocks (indented lines joined). */
export function frontmatter(text) {
  const m = /^---\r?\n([\s\S]*?)\r?\n---/.exec(text);
  if (!m) return {};
  const out = {};
  let key = null;
  for (const line of m[1].split(/\r?\n/)) {
    const kv = /^(\w[\w-]*):\s*(.*)$/.exec(line);
    if (kv) {
      key = /^[>|]-?$/.test(kv[2]) ? kv[1] : null;
      out[kv[1]] = key ? '' : kv[2].replace(/^['"]|['"]$/g, '');
    } else if (key && /^\s+\S/.test(line)) {
      out[key] = `${out[key]} ${line.trim()}`.trim();
    }
  }
  return out;
}

// ---------------------------------------------------------------- config / stack

export function workspaces() {
  return detectWorkspaces(ROOT);
}

const CI_MARK = new RegExp(`^# Generated by \`npx ${escapeRe(NAME)} (?:init|sync)\``);
const LEGACY_CI = '.github/workflows/aquila-gates.yml';
const ciSlug = (prefix) => prefix.replace(/\/$/, '').replaceAll(/[^\w.-]+/g, '-');
/** GitHub only reads workflows from <repo>/.github/workflows: one file per project in a monorepo. */
const CI_CALLER = REPO.prefix
  ? atTop(`.github/workflows/aquila-gates-${ciSlug(REPO.prefix)}.yml`)
  : '.github/workflows/aquila-gates.yml';

/** CI can only run `npx aquila-ai` when the project declares it in package.json. */
const isInstalled = () => {
  if (!existsSync(p('package.json'))) return false;
  const pkg = readJson('package.json');
  return Boolean(pkg.devDependencies?.[`${NAME}`] ?? pkg.dependencies?.[`${NAME}`]);
};

const LOCKFILE = { npm: 'package-lock.json', pnpm: 'pnpm-lock.yaml', yarn: 'yarn.lock' };
/** `ci.workflow: false` — the project runs check and gate ci from its own pipeline. */
const wantsWorkflow = (cfg) => cfg.ci?.workflow !== false;

/** The steps the generated workflow runs: what a project's own pipeline must run with `ci.workflow: false`. */
const ciSteps = () => [
  `      - name: ${NAME} check (links, budgets, adapters)`,
  `        run: npx ${NAME} check`,
  `      - name: ${NAME} gate ci (gates from docs/ai/aquila.json)`,
  `        run: npx ${NAME} gate ci`,
];

/** A plain YAML scalar when safe; otherwise double-quoted (multi-line, `: `, ` #`, a leading indicator). */
const yamlScalar = (v) => {
  const text = String(v);
  return /\n|: | #|^[\s\-?:,[\]{}#&*!|>'"%@`]|\s$/.test(text) ? JSON.stringify(text) : text;
};

/** Self-contained CI workflow with the project's install, runtime and services (`ci` in aquila.json). */
export function ciCaller(cfg, prefix = '') {
  const ci = cfg.ci ?? {};
  const quote = (v) => `'${String(v).replaceAll("'", "''")}'`;
  const dir = prefix.replace(/\/$/, '');
  // In a monorepo: run inside the project and only when its folder (or this workflow) changes.
  const paths = dir
    ? ['    paths:', `      - ${quote(`${dir}/**`)}`, `      - ${quote(posix(relative(REPO.top, p(CI_CALLER))))}`]
    : [];
  const map = (obj, indent) =>
    Object.entries(obj ?? {}).map(([k, v]) => `${' '.repeat(indent)}${k}: ${quote(v)}`);
  // Service containers (e.g. Postgres) so `gate ci` runs the full suite, not only what needs no service.
  const services = Object.entries(ci.services ?? {}).flatMap(([name, s]) => [
    `      ${name}:`,
    `        image: ${quote(s.image)}`,
    ...(s.env ? ['        env:', ...map(s.env, 10)] : []),
    ...(s.ports?.length ? ['        ports:', ...s.ports.map((port) => `          - ${quote(port)}`)] : []),
    ...(s.options ? [`        options: ${quote(s.options)}`] : []),
  ]);
  return [
    `# Generated by \`npx ${NAME} sync\` from docs/ai/aquila.json → ci — commit it, do not edit`,
    '# (`check` fails if it drifts; `ci.workflow: false` turns it off).',
    `name: ${dir ? `aquila-gates (${dir})` : 'aquila-gates'}`,
    '',
    'on:',
    '  pull_request:',
    ...paths,
    '  push:',
    '    branches: [develop, main, master]',
    ...paths,
    '',
    'permissions:',
    '  contents: read',
    '',
    'jobs:',
    '  gates:',
    '    runs-on: ubuntu-latest',
    ...(dir ? ['    defaults:', '      run:', `        working-directory: ${quote(dir)}`] : []),
    ...(services.length ? ['    services:', ...services] : []),
    ...(ci.env && Object.keys(ci.env).length ? ['    env:', ...map(ci.env, 6)] : []),
    '    steps:',
    '      - uses: actions/checkout@v4',
    '        with:',
    '          fetch-depth: 0',
    '          persist-credentials: false',
    '      - uses: actions/setup-node@v4',
    '        with:',
    `          node-version: ${quote(ci['node-version'] ?? '22')}`,
    ...(ci.cache ? [`          cache: ${quote(ci.cache)}`] : []),
    ...(ci.cache && dir ? [`          cache-dependency-path: ${quote(`${dir}/${LOCKFILE[ci.cache]}`)}`] : []),
    ...(ci['install-command'] ? [`      - run: ${yamlScalar(ci['install-command'])}`] : []),
    ...ciSteps(),
    '',
  ].join('\n');
}

/** What to paste into an existing pipeline when `ci.workflow` is false. */
function ciSnippet() {
  const dir = REPO.prefix ? `${REPO.prefix.replace(/\/$/, '')}` : '';
  return [
    `# after checkout (fetch-depth: 0), setup-node and the install${dir ? `, with working-directory: ${dir}` : ''}:`,
    ...ciSteps().map((line) => line.slice(4)),
  ].join('\n');
}

/**
 * The `lint-aquila` gate follows `lint.level` (changed in aquila.json or by `/aquila-config`): it leaves
 * with `off`, joins when the engine is installed and, without an engine, sits in `lint.pending`.
 * Returns the note, or null.
 */
function syncLintGate(cfg) {
  const lint = (cfg.lint ??= {});
  if (!lint.level || lint.level === 'off' || !lint.engine) {
    const had = Boolean(cfg.gates?.['lint-aquila'] || lint.pending);
    delete cfg.gates?.['lint-aquila'];
    for (const phase of Object.keys(cfg.hooks ?? {}))
      cfg.hooks[phase] = cfg.hooks[phase].filter((n) => n !== 'lint-aquila');
    delete lint.pending;
    return had ? `✓ ${CONFIG}: lint ${lint.level ?? 'off'} — lint-aquila removed from gates` : null;
  }
  if (cfg.gates?.['lint-aquila']) return null;
  const missing = missingTool(lint.engine, ROOT);
  if (missing) {
    if (lint.pending === missing) return null;
    lint.pending = missing;
    return `! ${CONFIG}: lint-aquila left out of the gates until the engine is installed: ${missing}`;
  }
  const wasPending = Boolean(lint.pending);
  delete lint.pending;
  if (addLintGate((cfg.gates ??= {}), (cfg.hooks ??= {})))
    return `✓ ${CONFIG}: lint ${lint.level} — lint-aquila in pre-push and ci`;
  return wasPending ? `✓ ${CONFIG}: lint engine installed` : null;
}

function loadConfig() {
  if (!existsSync(p(CONFIG))) throw new Error(`${CONFIG} missing — run: npx ${NAME} init`);
  return readJson(CONFIG);
}

function configValidation(cfg) {
  const schema = JSON.parse(readFileSync(join(PKG, 'schema', 'aquila.schema.json'), 'utf8'));
  return checkConfig(schema, cfg);
}

function assertConfig(cfg) {
  const config = configValidation(cfg);
  if (config.errors.length)
    throw new Error(
      `${CONFIG} invalid (schema: .aquila/schema/aquila.schema.json):\n  ${config.errors.join('\n  ')}`,
    );
  return cfg;
}

// ---------------------------------------------------------------- adapters

/** Definition of done with the project's real commands (saves opening done.md + aquila.json each task). */
function doneSection(cfg) {
  // done.gates is independent of CI: a gate that needs a local service stays a done criterion.
  const lines = (cfg.done?.gates?.length ? cfg.done.gates : (cfg.hooks?.ci ?? Object.keys(cfg.gates ?? {})))
    .map((name) => {
      const g = cfg.gates?.[name];
      if (!g) return null;
      const cmd = typeof g === 'string' ? g : g.cmd;
      const when =
        typeof g === 'object' && Array.isArray(g.when)
          ? ` — CI only when these change: ${g.when.join(', ')}`
          : typeof g === 'object' && g.when
            ? ` — legacy note (does not condition execution): ${g.when}`
            : '';
      return `- [ ] ${name}: \`${cmd}\`${when}`;
    })
    .filter(Boolean);
  const { enforced, ...limits } = cfg.coverage ?? {};
  const coverage = Object.entries(limits)
    .map(([k, v]) => `${k} ≥ ${v}`)
    .join(', ');
  // Only say "enforced" when a coverage gate fails below the threshold (aquila.json → coverage.enforced).
  const applied = cfg.gates?.coverage && enforced !== false;
  const how = applied
    ? 'enforced by the `coverage` command'
    : 'target — no gate enforces it';
  return [
    '**Done** (every gate that runs must pass; one with a `when` list runs in CI only when those paths change, always in local hooks; checklist: `.aquila/core/done.md`):',
    '',
    ...(lines.length
      ? lines
      : ['- [ ] (no gates defined — define them in `docs/ai/aquila.json` → `gates`)']),
    ...(coverage ? [`- Project coverage: ${coverage} (${how}).`] : []),
  ].join('\n');
}

const prMaxFiles = (cfg) => cfg.review?.prMaxFiles ?? 30;

function prLine(cfg) {
  const max = prMaxFiles(cfg);
  return `**Small PRs:** more than ${max} changed files (not counting generated ones: \`.aquila/\`, \`.aquila-hooks/\`, routers, \`.claude/commands/aquila-*\`, \`aquila-gates*.yml\`) → propose PRs of ≤ ${max} files, each green (\`.aquila/core/workflow.md\` §5).`;
}

/** Major of the stack's framework: installed version first (hoisted too), else the range in package.json. */
export const frameworkMajor = (root = ROOT) => dependencyMajor(root, PROFILE.framework);

function languageLine(cfg) {
  const l = { code: 'en', docs: 'en', answers: 'en', ...cfg.language };
  return `language: code ${l.code}, docs ${l.docs}, answers to the dev ${l.answers}.`;
}

/**
 * A standing commit instruction from the owner replaces "commit only when asked" (workflow.autoCommit:
 * true | "commit" → commit only; "commit+push" → commit and push).
 */
function commitLine(cfg) {
  const auto = cfg.workflow?.autoCommit;
  if (!auto) return '';
  const what =
    auto === 'commit+push'
      ? 'commit and push each green change unasked'
      : 'commit each green change unasked; push only when asked';
  return `\n**Commits:** standing instruction from the project owner (\`workflow.autoCommit\`): ${what}.\n`;
}

function skillDirs(base) {
  return existsSync(base)
    ? readdirSync(base)
        .filter((n) => existsSync(join(base, n, 'SKILL.md')))
        .map((n) => join(base, n))
    : [];
}

/** Generated files for the config: [{ path, content, router?, versioned? }]. */
export function plan(cfg) {
  const tools = new Set(cfg.tools);
  const always = readFileSync(join(PKG, 'core', 'always.md'), 'utf8').trim();
  const gate = `npx ${NAME} gate ci`;
  const level = cfg.lint?.level ?? 'off';
  const quality =
    level === 'off'
      ? ''
      : `\n**Quality (lint \`${level}\`):** write code that already passes \`npx ${NAME} lint rules\` (Sonar-aligned; \`aquila-review\` checks them).\n`;
  const major = frameworkMajor();
  const out = [
    {
      path: 'AGENTS.md',
      router: true,
      content: block(
        `# ${cfg.project} — instructions for AI agents\n\n${always}\n${quality}${commitLine(cfg)}\n${prLine(cfg)}\n\n${doneSection(cfg)}\n\n**Project:** ${cfg.project} · ${PROFILE.stack} ${major ?? '?'} (conventions: \`.aquila/core/${PROFILE.id}.md\`) · all gates: \`${gate}\` · config \`${CONFIG}\` · ${languageLine(cfg)}`,
      ),
    },
  ];
  // Skills are never copied or linked to the root. Claude reads aquila-ai's through the plugin; Copilot
  // through chat.agentSkillsLocations; Codex through AGENTS.md (it reads the requested SKILL.md). Project
  // skills (docs/ai/skills) are docs the CONTEXT.md map points to.
  if (tools.has('claude')) {
    out.push({ path: 'CLAUDE.md', router: true, content: block('@AGENTS.md') });
    // `/aquila-*` shortcuts for the user only: the model already sees the plugin skill.
    for (const dir of skillDirs(join(PKG, 'skills'))) {
      const name = basename(dir);
      out.push({
        path: `.claude/commands/${name}.md`,
        shared: true,
        content: `---\ndescription: Shortcut for the aquila:${name} skill\ndisable-model-invocation: true\n---\n<!-- ${MARK} -->\nUse the \`aquila:${name}\` skill with: $ARGUMENTS\n`,
      });
    }
  }
  if (tools.has('copilot')) {
    out.push({
      path: '.github/copilot-instructions.md',
      router: true,
      content: block(copilotBody(cfg)),
    });
    // Copilot (PR review, coding agent, VS Code opened at the root) reads .github/ only at the repository
    // root: a project in a subfolder gets a root instructions file scoped to its folder.
    if (REPO.prefix) {
      const dir = REPO.prefix.replace(/\/$/, '');
      const body = copilotBody(cfg).replaceAll('](../', `](../../${dir}/`);
      out.push({
        path: atTop(`${INSTRUCTIONS}/aquila-${ciSlug(REPO.prefix)}.instructions.md`),
        shared: true,
        content: `---\napplyTo: '${dir}/**'\n---\n<!-- ${MARK} -->\n\n${body.replace(/^# .*\n/, `# ${cfg.project} (\`${dir}/\`) — GitHub Copilot\n`)}\n`,
      });
    }
  }
  // CI caller: versioned in any mode; regenerated by sync like the other adapters.
  if (isInstalled() && wantsWorkflow(cfg))
    out.push({ path: CI_CALLER, versioned: true, content: ciCaller(cfg, REPO.prefix) });
  return out;
}

/** aquila-ai managed block inside a router (the rest of the file belongs to the project). */
const BEGIN = `<!-- >>> ${MARK} -->`;
const END = `<!-- <<< ${NAME} -->`;
const BLOCK_RE = new RegExp(
  `<!-- >>> generated by ${escapeRe(NAME)} [^\\n]*-->[\\s\\S]*?<!-- <<< ${escapeRe(NAME)} -->\\n?`,
);
const lf = (text) => text.replaceAll('\r\n', '\n');
function block(body) {
  return `${BEGIN}\n\n${body.trim()}\n\n${END}\n`;
}

/**
 * Copilot PR review and coding agent on GitHub read this file and the `.instructions.md` files, but not
 * node_modules. Ordered by value for review: project rules first, then the checklist and finally the lint
 * list (the longest). The definition of done is not repeated: Copilot in VS Code already loads AGENTS.md.
 */
function copilotBody(cfg) {
  const level = cfg.lint?.level ?? 'off';
  const rules = contextSection(cfg);
  return [
    `# ${cfg.project} — GitHub Copilot`,
    '',
    `Method: [\`AGENTS.md\`](../AGENTS.md) (${NAME}; definition of done) · project map: [\`docs/ai/CONTEXT.md\`](../docs/ai/CONTEXT.md) · per-folder rules: \`.github/instructions/\` (\`applyTo\`).`,
    ...(rules ? ['', '## Project rules (from `docs/ai/CONTEXT.md`)', '', rules] : []),
    '',
    '## When reviewing a PR',
    '',
    '1. Correctness and the project rules above, one by one over the diff; swallowed or unlogged errors.',
    '2. Right layer: code in the wrong folder or crossing two responsibilities is a bug.',
    '3. Tests: cover the changed behaviour and invalid/failure cases where relevant; real flows when integration/wiring is affected; gaps justified; asserts on exact values and arguments; no `only`/`skip`.',
    '4. Doc-sync: did architecture, an event, a schema or a route change without updating `docs/c4/`, the catalog or the track?',
    `5. Size: more than ${prMaxFiles(cfg)} changed files → ask for the PR to be split into incremental PRs of up to ${prMaxFiles(cfg)} files.`,
    `6. Style: comments that only repeat the code; ${languageLine(cfg)}`,
    ...(level === 'off'
      ? []
      : [
          `7. Quality (lint \`${level}\`, Sonar equivalents): ${lintRules(level)
            .map((r) => r.title)
            .join(' · ')}.`,
        ]),
    '',
    'One line per finding, most severe first: `file:line — problem → fix`.',
  ].join('\n');
}

/**
 * The invariants/architectural rules section of CONTEXT.md (heading containing one of
 * `review.contextSections`), with relative links rewritten for `.github/`.
 */
function contextSection(cfg) {
  if (!existsSync(p('docs/ai/CONTEXT.md'))) return '';
  const names = cfg.review?.contextSections ?? ['invariant', 'architectural rules'];
  const lines = lf(read('docs/ai/CONTEXT.md')).split('\n');
  const start = lines.findIndex(
    (l) => /^#{2,3} /.test(l) && names.some((n) => l.toLowerCase().includes(n.toLowerCase())),
  );
  if (start < 0) return '';
  const depth = /^#+/.exec(lines[start])[0].length;
  const stop = lines.findIndex((l, i) => i > start && new RegExp(`^#{1,${depth}} `).test(l));
  const text = lines
    .slice(start + 1, stop < 0 ? undefined : stop)
    // The template's own examples (`- <e.g.: …>`, pt `<ex.: …>`) are not project rules.
    .filter((l) => !/^\s*[-*]\s*<(?:e\.g\.|ex\.):.*>\s*$/.test(l))
    .join('\n')
    .trim();
  return text.replaceAll(/\]\(([^)\s]+)\)/g, (whole, target) => {
    if (/^(?:[a-z][a-z0-9+.-]*:|#)/i.test(target)) return whole;
    const [path, anchor] = target.split('#');
    const rel = posixPath.relative('.github', posixPath.join('docs/ai', path));
    return `](${rel}${anchor === undefined ? '' : `#${anchor}`})`;
  });
}

function vscodeSettings(prefix = '') {
  return {
    'chat.agentFilesLocations': { [`${prefix}.aquila/adapters/copilot/agents`]: true },
    'chat.agentSkillsLocations': { [`${prefix}.aquila/skills`]: true },
  };
}

function isGenerated(path) {
  if (!existsSync(p(path)) || !lstatSync(p(path)).isFile()) return false;
  const text = read(path);
  return text.includes(MARK) || CI_MARK.test(text);
}

const norm = (path) => {
  const clean = resolve(path.replace(/^\\\\\?\\/, '')).replace(/[\\/]+$/, '');
  return process.platform === 'win32' ? clean.toLowerCase() : clean;
};
const isUnder = (path, base) =>
  path === norm(base) ||
  path.startsWith(`${norm(base)}${process.platform === 'win32' ? '\\' : '/'}`);

/** Normalized target of a symlink/junction, or null if not a link. */
function linkTarget(path) {
  try {
    if (!lstatSync(p(path)).isSymbolicLink()) return null;
    return norm(resolve(dirname(p(path)), readlinkSync(p(path))));
  } catch {
    return null;
  }
}

/** Removes only the link (never the target's content). */
function removeLink(path) {
  try {
    unlinkSync(p(path));
  } catch {
    rmdirSync(p(path));
  }
}

const excludeBlock = (tag) =>
  new RegExp(`# >>> ${escapeRe(tag)} \\(generated[\\s\\S]*?# <<< ${escapeRe(tag)}(?:\\n|$)`);

/** info/exclude is anchored at the repo root: one block per project, paths prefixed with its folder. */
function writeExclude(paths) {
  const file = git('rev-parse', '--git-path', 'info/exclude');
  if (!file) return false;
  const full = resolve(ROOT, file);
  let current = existsSync(full) ? readFileSync(full, 'utf8') : '';
  const tag = REPO.prefix ? `${NAME} ${REPO.prefix}` : `${NAME}`;
  // 0.1.0 wrote a root-anchored block from subfolders too; it is ours unless a root project is registered.
  if (REPO.prefix && !readRegistry(REPO.top).some((e) => e.pkg === `${NAME}` && e.dir === '.'))
    current = current.replace(excludeBlock(`${NAME}`), '');
  // Paths are the project's (some at the repository root, e.g. ../.vscode/settings.json): anchor them at the root.
  const anchored = [...new Set(paths.map((x) => `/${posix(relative(REPO.top, p(x)))}`))];
  const block = `# >>> ${tag} (generated; do not edit)\n${anchored.join('\n')}\n# <<< ${tag}\n`;
  const re = excludeBlock(tag);
  const next = re.test(current)
    ? current.replace(re, () => block)
    : `${current}${current && !current.endsWith('\n') ? '\n' : ''}${block}`;
  mkdirSync(dirname(full), { recursive: true });
  writeFileSync(full, next);
  return true;
}

/**
 * JSON with comments and trailing commas (JSONC, the VS Code settings format) → object. Respects
 * strings; returns null if it still isn't JSON.
 */
export function parseJsonc(text) {
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '"') {
      const end = /"(?:[^"\\]|\\.)*"/y;
      end.lastIndex = i;
      const m = end.exec(text);
      if (!m) return null;
      out += m[0];
      i += m[0].length - 1;
    } else if (c === '/' && text[i + 1] === '/') {
      while (i < text.length && text[i] !== '\n') i++;
      out += '\n';
    } else if (c === '/' && text[i + 1] === '*') {
      const close = text.indexOf('*/', i + 2);
      i = close < 0 ? text.length : close + 1;
    } else out += c;
  }
  try {
    return JSON.parse(out.replaceAll(/,(\s*[}\]])/g, '$1'));
  } catch {
    return null;
  }
}

/** Are the `patch` keys (one level deep) already in `current`? */
const hasKeys = (current, patch) =>
  Object.entries(patch).every(([k, v]) =>
    typeof v === 'object'
      ? Object.entries(v).every(
          ([kk, vv]) => JSON.stringify(current?.[k]?.[kk]) === JSON.stringify(vv),
        )
      : current?.[k] === v,
  );

/**
 * Adds aquila-ai keys to a settings JSON. A file with comments (JSONC) is never rewritten — the comments
 * would be lost: it is only checked and, if something is missing, the note says what to add.
 */
function mergeJson(file, patch) {
  let current = {};
  if (existsSync(p(file))) {
    const raw = read(file);
    try {
      current = JSON.parse(raw);
    } catch {
      const parsed = parseJsonc(raw);
      if (parsed && hasKeys(parsed, patch)) return null;
      return `✗ ${file} has comments (JSONC) and I won't rewrite it — add by hand: ${JSON.stringify(patch)}`;
    }
  }
  const next = { ...current };
  for (const [k, v] of Object.entries(patch))
    next[k] = typeof v === 'object' ? { ...current[k], ...v } : v;
  if (JSON.stringify(next) === JSON.stringify(current)) return null;
  mkdirSync(dirname(p(file)), { recursive: true });
  writeFileSync(p(file), `${JSON.stringify(next, null, 2)}\n`);
  return `✓ ${file} (${NAME} keys)`;
}

/** Removes from a settings JSON the keys aquila-ai put there (tool turned off). */
function unmergeJson(file, patch) {
  if (!existsSync(p(file))) return null;
  let current;
  try {
    current = JSON.parse(read(file));
  } catch {
    return null; // JSONC: the package never wrote it, it won't rewrite it now
  }
  const next = { ...current };
  for (const [k, v] of Object.entries(patch)) {
    if (typeof v !== 'object' || typeof next[k] !== 'object') continue;
    next[k] = { ...next[k] };
    for (const kk of Object.keys(v)) delete next[k][kk];
    if (!Object.keys(next[k]).length) delete next[k];
  }
  if (JSON.stringify(next) === JSON.stringify(current)) return null;
  if (Object.keys(next).length) writeFileSync(p(file), `${JSON.stringify(next, null, 2)}\n`);
  else rmSync(p(file));
  return `✓ removed ${NAME} keys from ${file}`;
}

/** Claude Code settings in team mode: plugin enabled + marketplace (the installed package). */
const CLAUDE_TEAM = {
  extraKnownMarketplaces: {
    [NAME]: { source: { source: 'directory', path: './.aquila' } },
  },
  enabledPlugins: { [`aquila@${NAME}`]: true },
};

/** Tool settings: [file, aquila-ai keys, active?]. */
function settingsSpec(cfg) {
  const copilot = cfg.tools.includes('copilot');
  return [
    ['.vscode/settings.json', vscodeSettings(), copilot],
    ['.claude/settings.json', CLAUDE_TEAM, cfg.tools.includes('claude') && cfg.mode === 'team'],
    // VS Code opened at the repository root reads only the root .vscode/: point it at this project's method.
    ...(REPO.prefix ? [[atTop('.vscode/settings.json'), vscodeSettings(REPO.prefix), copilot]] : []),
  ];
}

/** [path inside .aquila, content] for every method file. */
function methodFiles() {
  const list = (rel) =>
    statSync(join(PKG, rel)).isDirectory()
      ? readdirSync(join(PKG, rel)).flatMap((n) => list(posix(join(rel, n))))
      : [rel];
  const readme = [
    `# .aquila — ${NAME} ${version()}`,
    '',
    `Generated by \`npx ${NAME} sync\` from the installed package: do not edit, commit it.`,
    `Agents (local and cloud) read the method from here. Update: \`npm i -D ${NAME}@latest && npx ${NAME} sync\`.`,
    '',
  ].join('\n');
  return [
    ...METHOD_ITEMS.flatMap(list).map((rel) => [rel, readFileSync(join(PKG, rel), 'utf8')]),
    ['README.md', readme],
  ];
}

const listMethod = (dir = METHOD) =>
  existsSync(p(dir))
    ? readdirSync(p(dir)).flatMap((n) => {
        const rel = posix(join(dir, n));
        return statSync(p(rel)).isDirectory() ? listMethod(rel) : [rel];
      })
    : [];

/** Files in .aquila/ that differ from the installed package (CRLF is no difference). */
function methodDrift() {
  const want = new Map(methodFiles().map(([rel, text]) => [`${METHOD}/${rel}`, text]));
  const drift = [...want]
    .filter(([path, text]) => !existsSync(p(path)) || lf(read(path)) !== lf(text))
    .map(([path]) => `${path} out of date`);
  for (const path of listMethod().filter((f) => !want.has(f)))
    drift.push(`${path} not in ${NAME} ${version()}`);
  return drift.length > 5 ? [...drift.slice(0, 5), `… ${drift.length - 5} more in ${METHOD}/`] : drift;
}

/** Copies the method into .aquila/ (overwrites; removes files the package no longer has). */
function syncMethod() {
  const files = methodFiles();
  const want = new Set(files.map(([rel]) => `${METHOD}/${rel}`));
  let changed = 0;
  for (const [rel, text] of files) {
    const path = `${METHOD}/${rel}`;
    if (!existsSync(p(path)) || lf(read(path)) !== lf(text)) {
      mkdirSync(dirname(p(path)), { recursive: true });
      writeFileSync(p(path), text);
      changed++;
    }
  }
  for (const path of listMethod().filter((f) => !want.has(f))) {
    rmSync(p(path));
    changed++;
  }
  // Folders left empty (e.g. the 0.1.0 .aquila/githooks).
  const prune = (dir) => {
    for (const n of readdirSync(p(dir))) if (statSync(p(dir, n)).isDirectory()) prune(posix(join(dir, n)));
    if (dir !== METHOD && !readdirSync(p(dir)).length) rmdirSync(p(dir));
  };
  if (existsSync(p(METHOD))) prune(METHOD);
  return changed
    ? [`✓ ${METHOD}/ — ${NAME} ${version()} method (${changed} file(s) updated; commit it)`]
    : [];
}

/** The shared dispatcher in <repo>/.aquila-hooks and this project's line in its registry. */
function syncHooks() {
  if (!REPO.git) return [];
  const { written, notes } = writeDispatcher(REPO.top, PKG);
  notes.push(...written.map((file) => `✓ ${DISPATCH_DIR}/${file} (hook dispatcher; commit it)`));
  if (register(REPO.top, NAME, REPO.dir)) notes.push(`✓ ${REGISTRY}: ${NAME} ${REPO.dir} (commit it)`);
  // Windows versions the hooks 100644 (core.fileMode=false): Linux/macOS clones would never run them.
  const hooks = dispatcherFiles().filter((f) => !f.endsWith('.gitattributes'));
  for (const path of stageExecutable(REPO.top, hooks))
    notes.push(`✓ ${path} staged as executable (100755; commit it)`);
  // A pre-0.2.0 aquila hooksPath runs nothing from a subfolder (git resolves it from the root): safe to move.
  const hooksPath = git('config', '--get', 'core.hooksPath');
  if (hooksPathKind(REPO.top, hooksPath) === 'legacy') {
    git('config', 'core.hooksPath', DISPATCH_DIR);
    notes.push(`✓ git config core.hooksPath ${hooksPath} → ${DISPATCH_DIR} (shared dispatcher)`);
  }
  return notes;
}

export function sync() {
  assertOwnMethod();
  const cfg = assertConfig(loadConfig());
  const notes = [];
  const before = JSON.stringify(cfg);
  const lintNote = syncLintGate(cfg);
  if (JSON.stringify(cfg) !== before) writeFileSync(p(CONFIG), `${JSON.stringify(cfg, null, 2)}\n`);
  if (lintNote) notes.push(lintNote);
  notes.push(...syncMethod());
  const items = plan(cfg);
  const wanted = new Set(items.map((i) => i.path));

  const team = cfg.mode === 'team';
  for (const item of items) {
    const raw = existsSync(p(item.path)) ? read(item.path) : null;
    const current = raw === null ? null : lf(raw);
    let next = item.content;
    let note = `✓ ${item.path}`;
    if (current !== null && item.router) {
      if (BLOCK_RE.test(current)) next = current.replace(BLOCK_RE, () => item.content);
      else if (!team && git('ls-files', '--error-unmatch', item.path)) {
        // In local mode nothing from aquila-ai is versioned: touching a team router would leave it modified.
        notes.push(
          `! ${item.path} is versioned and in local mode I don't touch it — use mode team to let ${NAME} manage it`,
        );
        continue;
      } else if (!current.startsWith(`<!-- ${MARK}`)) {
        // Project router: the aquila-ai block goes on top and existing content stays intact.
        next = `${item.content}\n${current}`;
        note = `✓ ${item.path}: ${NAME} block injected at the top (existing content kept)`;
      }
    } else if (current !== null && !isGenerated(item.path)) {
      notes.push(`✗ ${item.path} exists and was not generated by ${NAME} — left untouched`);
      continue;
    }
    if (current === next) continue;
    mkdirSync(dirname(p(item.path)), { recursive: true });
    // Keep the existing file's line endings (a CRLF router doesn't become LF).
    writeFileSync(p(item.path), raw?.includes('\r\n') ? next.replaceAll('\n', '\r\n') : next);
    notes.push(note);
  }
  // 0.1.0 wrote the workflow inside the project; from a subfolder GitHub never ran it.
  if (REPO.prefix && isGenerated(LEGACY_CI)) {
    rmSync(p(LEGACY_CI));
    notes.push(`✓ removed ${REPO.prefix}${LEGACY_CI} (GitHub only runs workflows from the repository root)`);
  }
  // ci.workflow: false — the project's own pipeline runs check and gate ci (doctor shows the steps).
  if (!wantsWorkflow(cfg) && isGenerated(CI_CALLER)) {
    rmSync(p(CI_CALLER));
    notes.push(`✓ removed ${CI_CALLER} (ci.workflow: false)`);
  }
  notes.push(...syncHooks());

  // Remove generated adapters no longer in the plan (tool turned off, skill removed) and stray skill
  // links in .agents/skills and .claude/skills (never the target's content).
  for (const dir of ['.claude/commands', '.claude/skills', '.agents/skills']) {
    if (!existsSync(p(dir))) continue;
    for (const name of readdirSync(p(dir))) {
      const rel = `${dir}/${name}`;
      if (wanted.has(rel)) continue;
      const target = linkTarget(rel);
      if (target && (isUnder(target, PKG) || isUnder(target, p('docs/ai/skills')))) removeLink(rel);
      else if (isGenerated(rel)) rmSync(p(rel));
      else continue;
      notes.push(`✓ removed ${rel}`);
    }
    if (dir === '.agents/skills' && !readdirSync(p(dir)).length) {
      rmdirSync(p(dir));
      if (!readdirSync(p('.agents')).length) rmdirSync(p('.agents'));
    }
  }
  for (const router of ROUTERS) {
    if (wanted.has(router) || !existsSync(p(router))) continue;
    const current = lf(read(router));
    const rest = BLOCK_RE.test(current)
      ? current.replace(BLOCK_RE, '').replace(/^\n+/, '')
      : current.startsWith(`<!-- ${MARK}`)
        ? ''
        : null;
    if (rest === null) continue;
    if (rest.trim()) writeFileSync(p(router), rest);
    else rmSync(p(router));
    notes.push(`✓ removed ${rest.trim() ? `the ${NAME} block from ${router}` : router}`);
  }

  // Settings: aquila-ai keys go in when the tool is active and out when it is turned off.
  // The Claude marketplace (package directory) is shared in team: without it a teammate can't install the plugin.
  for (const [file, patch, active] of settingsSpec(cfg)) {
    // Local mode: a settings file the team versions is not ours to change (it would show up modified).
    if (versionedInLocal(cfg, file)) {
      if (active && !hasKeys(parseJsonc(read(file)) ?? {}, patch))
        notes.push(`! ${file} is versioned and in local mode I don't touch it — add by hand ${JSON.stringify(patch)} or use mode team`);
      continue;
    }
    const note = active ? mergeJson(file, patch) : unmergeJson(file, patch);
    if (note) notes.push(note);
  }
  if (existsSync(p('.claude/commands')) && !readdirSync(p('.claude/commands')).length) {
    rmdirSync(p('.claude/commands'));
  }

  // Method ephemerals (core/workflow.md) are never versioned.
  const excluded = [
    'plan.md',
    'spec.md',
    // `/aquila-deep-audit` reports: the dev decides what to share.
    'audit_*.md',
    LOCAL,
    // In team the routers and `/aquila-*` shortcuts are the team's (versioned); in local, this machine's.
    ...items.filter((i) => !i.versioned && !(team && (i.router || i.shared))).map((i) => i.path),
  ];
  // In local mode the VS Code settings are this machine's only; in team the chat.* keys are the team's.
  for (const [file] of settingsSpec(cfg).filter(([f]) => f.endsWith('.vscode/settings.json')))
    if (!team && !git('ls-files', '--error-unmatch', file)) excluded.push(file);
  if (!writeExclude(excluded)) notes.push('! no git repository: nothing was excluded from git');
  if (team) {
    // In team mode the routers, VS Code settings and enabled plugin are versioned: a project
    // .gitignore must not hide them.
    const shared = [...items.filter((i) => i.router).map((i) => i.path)];
    if (cfg.tools.includes('copilot')) shared.push('.vscode/settings.json');
    if (cfg.tools.includes('claude')) shared.push('.claude/settings.json');
    for (const path of shared.filter((f) => git('check-ignore', '--no-index', f))) {
      notes.push(
        `✗ ${path} is in the project's .gitignore, but mode team versions it — remove it from .gitignore`,
      );
    }
  }
  return notes;
}

// ---------------------------------------------------------------- check

function checkAdapters(cfg) {
  const drift = [];
  for (const item of plan(cfg)) {
    const exists = existsSync(p(item.path));
    const current = exists ? lf(read(item.path)) : '';
    // In routers only the aquila-ai block counts; the rest belongs to the project. CRLF is no difference.
    const ours = item.router ? (current.match(BLOCK_RE)?.[0] ?? null) : current;
    if (exists && ours !== null && isGenerated(item.path) && ours !== item.content)
      drift.push(`${item.path} out of date`);
    if (cfg.mode === 'team' && item.router && (!exists || ours === null))
      drift.push(`${item.path} ${exists ? `without the ${NAME} block` : 'missing'} (mode: team)`);
  }
  return [...drift, ...settingsDrift(cfg)];
}

/**
 * aquila-ai keys missing from the active tools' settings (also in JSONC, which sync doesn't rewrite).
 * In local mode only if the file exists — local settings aren't there in CI.
 */
/**
 * Codex concatenates the AGENTS.md files from the repository root down to the working folder and cuts at
 * 32 KiB (project_doc_max_bytes). Each AGENTS.md of the project is the end of one chain; branches that are
 * never read together are not added up. `.aquila/` (the method copy) is not a router.
 */
const CODEX_MAX_BYTES = 32 * 1024;
function codexChains() {
  const listed = git('ls-files', '--cached', '--others', '--exclude-standard', '--', ':(glob)**/AGENTS.md')
    .split('\n')
    .filter((f) => f && !/(^|\/)(\.aquila|node_modules)\//.test(f));
  if (existsSync(p('AGENTS.md'))) listed.push('AGENTS.md');
  const top = resolve(REPO.top);
  const over = [];
  for (const file of new Set(listed)) {
    let dir = dirname(p(file));
    let total = 0;
    for (;;) {
      if (existsSync(join(dir, 'AGENTS.md'))) total += statSync(join(dir, 'AGENTS.md')).size;
      if (resolve(dir) === top || dirname(dir) === dir) break;
      dir = dirname(dir);
    }
    if (total > CODEX_MAX_BYTES)
      over.push(`${file}: AGENTS.md chain from the repository root ${total} bytes > 32 KiB (Codex cuts the rest)`);
  }
  return over;
}

const versionedInLocal = (cfg, file) =>
  cfg.mode !== 'team' && existsSync(p(file)) && Boolean(git('ls-files', '--error-unmatch', file));

function settingsDrift(cfg, required = false) {
  const team = cfg.mode === 'team';
  const drift = [];
  for (const [file, patch, active] of settingsSpec(cfg)) {
    if (!active || (!team && !required && !existsSync(p(file)))) continue;
    if (!required && versionedInLocal(cfg, file)) continue;
    const parsed = existsSync(p(file)) ? parseJsonc(read(file)) : null;
    if (!parsed || !hasKeys(parsed, patch)) {
      drift.push(`${file} without the ${NAME} keys (${Object.keys(patch).join(', ')})`);
    }
  }
  return drift;
}

export function check(args = []) {
  for (const arg of args)
    if (!['--ready', '--verbose'].includes(arg))
      throw new Error(`unknown flag: ${arg} (valid: --ready, --verbose)`);
  const ready = args.includes('--ready');
  const verbose = args.includes('--verbose');
  const cfg = loadConfig();
  const config = configValidation(cfg);
  log(
    !config.errors.length,
    `${CONFIG}${config.errors.length ? ` invalid (schema: .aquila/schema/aquila.schema.json):\n  ${config.errors.join('\n  ')}` : ' valid'}`,
  );
  if (config.unknown.length)
    console.log(`! ${CONFIG}: keys outside the schema (typo?): ${config.unknown.join(', ')}`);
  if (config.legacyWhen.length)
    console.log(
      `! ${CONFIG}: text \`when\` in gates ${config.legacyWhen.join(', ')} does not filter execution; migrate to a list of path globs`,
    );
  if (config.errors.length) return 1;
  const { files, broken, over, uncovered } = inspectDocuments({
    root: ROOT,
    cfg,
    walk,
    routers: ROUTERS,
    instructions: INSTRUCTIONS,
    budgets: DEFAULT_BUDGETS,
    frontmatter,
    top: REPO.prefix ? atTop(INSTRUCTIONS) : null,
    prefix: REPO.prefix,
  });
  log(
    !broken.length,
    `links: ${files} files${broken.length ? `, ${broken.length} broken:\n  ${broken.join('\n  ')}` : ''}`,
  );
  over.push(...codexChains());
  log(
    !over.length,
    `budgets${over.length ? ` over the limit (move detail to references/ or docs/):\n  ${over.join('\n  ')}` : ''}`,
  );
  const drift = [...methodDrift(), ...checkAdapters(cfg)];
  log(
    !drift.length,
    `adapters${drift.length ? ` — run \`npx ${NAME} sync\`:\n  ${drift.join('\n  ')}` : ' in sync'}`,
  );
  if (!ready) for (const warning of docWarnings(ROOT)) console.log(warning);
  // A count, not a wall of paths: per-folder instructions are optional (`--verbose` lists them).
  if (uncovered.length) {
    const folders = [...new Set(uncovered.map((f) => posix(dirname(f))))];
    console.log(
      verbose
        ? `! ${uncovered.length} file(s) without per-folder instructions (warning):\n  ${uncovered.join('\n  ')}`
        : `ℹ ${uncovered.length} file(s) in ${folders.length} folder(s) without per-folder instructions (.github/instructions/, optional; check --verbose lists them)`,
    );
  }
  const location = locationIssues(cfg);
  log(
    !location.length,
    `hooks and CI location${location.length ? `:\n  ${location.join('\n  ')}` : (REPO.prefix ? ` (repository root: ${posix(relative(ROOT, REPO.top))})` : '')}`,
  );
  let failed = broken.length > 0 || over.length > 0 || drift.length > 0 || location.length > 0;
  if (ready) {
    const issues = readinessIssues(ROOT, cfg);
    for (const item of plan(cfg)) {
      if (!existsSync(p(item.path))) issues.push(`${item.path} missing → run sync`);
      else if (item.router && !BLOCK_RE.test(lf(read(item.path))))
        issues.push(`${item.path} without the ${NAME} block → resolve the mode and run sync`);
    }
    if (!isInstalled())
      issues.push(`${NAME} is not in package.json → npm i -D ${NAME}`);
    if (existsSync(p(CI_CALLER)) && !isGenerated(CI_CALLER))
      issues.push(
        `${CI_CALLER}: manual CI integration not verified → review that your pipeline runs check and gate ci; plain check does not require the generated workflow`,
      );
    issues.push(...settingsDrift(cfg, true));
    // core.hooksPath is relative to the repository root; `--git-path hooks` to the current directory.
    const configured = git('config', '--get', 'core.hooksPath');
    issues.push(
      ...(configured
        ? hookIssues(REPO.top, cfg, configured)
        : hookIssues(ROOT, cfg, git('rev-parse', '--git-path', 'hooks'))),
    );
    if (cfg.tools.includes('claude')) {
      const installed = claudePluginInstalled();
      if (installed !== true)
        issues.push(
          `Claude Code plugin ${installed === null ? 'not verified (CLI unavailable or failed)' : 'missing'} → ${pluginInstall()}`,
        );
    }
    log(
      !issues.length && !failed,
      issues.length || failed
        ? `readiness blocked${issues.length ? `:\n  ${issues.join('\n  ')}` : ' — fix the failures above'}`
        : 'technical readiness verified — review the docs for accuracy; gates were not run and remote CI was not checked',
    );
    failed ||= issues.length > 0;
  }
  return failed ? 1 : 0;
}

// ---------------------------------------------------------------- lint

export function lint(args) {
  return runLint(args, { root: ROOT, loadConfig });
}

// ---------------------------------------------------------------- gate

export const TOOL_MISSING = /not recognized|command not found|não é reconhecido|ENOENT|npx canceled/i;

function ciChangedFiles() {
  const eventPath = process.env.GITHUB_EVENT_PATH;
  if (!eventPath || !existsSync(eventPath))
    return { files: null, reason: 'GitHub event payload unavailable' };

  let event;
  try {
    event = JSON.parse(readFileSync(eventPath, 'utf8'));
  } catch (error) {
    return { files: null, reason: `invalid GitHub event payload: ${error.message}` };
  }
  if (!event || typeof event !== 'object')
    return { files: null, reason: 'GitHub event payload is not an object' };
  const pullRequest = event.pull_request;
  const base = pullRequest?.base?.sha ?? event.before;
  const head = process.env.GITHUB_SHA ?? event.after ?? pullRequest?.head?.sha;
  if (
    typeof base !== 'string' ||
    typeof head !== 'string' ||
    !/^[0-9a-f]{40,64}$/i.test(base) ||
    !/^[0-9a-f]{40,64}$/i.test(head) ||
    /^0+$/.test(base)
  ) {
    return { files: null, reason: 'the event has no comparable base/head commits' };
  }

  const range = pullRequest ? `${base}...${head}` : `${base}..${head}`;
  const result = spawnSync('git', ['diff', '--name-only', '--relative', '-z', '--no-renames', range], {
    cwd: ROOT,
    encoding: 'utf8',
  });
  if (result.status !== 0)
    return {
      files: null,
      reason: `git diff failed: ${(result.stderr || result.error?.message || '').trim()}`,
    };
  return { files: result.stdout.split('\0').filter(Boolean).map(posix) };
}

export function gate(phase) {
  if (!['ci', 'pre-commit', 'pre-push'].includes(phase))
    throw new Error(`invalid phase: ${phase} (valid: pre-commit, pre-push, ci)`);
  const cfg = loadConfig();
  const names =
    phase === 'ci' ? (cfg.hooks?.ci ?? Object.keys(cfg.gates)) : (cfg.hooks?.[phase] ?? []);
  if (!names.length) {
    // An empty local hook is the project's choice; in CI a "0/0 green" would be a gate that checks nothing.
    const ci = phase === 'ci';
    log(
      !ci,
      `no gates in phase ${phase} (${CONFIG} → hooks.${phase})${ci ? ' — CI cannot pass without checking anything' : ''}`,
    );
    return ci ? 1 : 0;
  }
  const hasConditionalGates =
    phase === 'ci' &&
    names.some((name) => cfg.gates?.[name] && Array.isArray(cfg.gates[name].when));
  const changes = hasConditionalGates ? ciChangedFiles() : null;
  if (changes && !changes.files)
    console.log(
      `! could not determine changed files (${changes.reason}); conditional gates run to be safe`,
    );
  let failed = 0;
  let skipped = 0;
  for (const name of names) {
    const spec = cfg.gates[name];
    if (!spec) {
      log(false, `${name}: gate not defined in ${CONFIG}`);
      failed++;
      continue;
    }
    if (
      Array.isArray(spec.when) &&
      (!spec.when.length ||
        spec.when.some((pattern) => typeof pattern !== 'string' || !pattern.trim()))
    ) {
      log(false, `${name}: when must contain non-empty path globs`);
      failed++;
      continue;
    }
    if (changes?.files && Array.isArray(spec.when)) {
      const patterns = spec.when.map(globToRegex);
      if (!changes.files.some((file) => patterns.some((pattern) => pattern.test(file)))) {
        console.log(`↷ ${name}: no changed file matches ${spec.when.join(', ')}`);
        skipped++;
        continue;
      }
    }
    const cmd = typeof spec === 'string' ? spec : spec.cmd;
    if (typeof cmd !== 'string' || !cmd.trim()) {
      log(false, `${name}: gate without a command (${CONFIG} → gates.${name}.cmd)`);
      failed++;
      continue;
    }
    const started = Date.now();
    const r = spawnSync(cmd, {
      cwd: ROOT,
      shell: true,
      encoding: 'utf8',
      maxBuffer: 64 * 1024 * 1024,
    });
    const secs = ((Date.now() - started) / 1000).toFixed(1);
    if (r.status === 0) {
      log(true, `${name} (${secs}s)`);
      continue;
    }
    failed++;
    log(false, `${name} (${secs}s): ${cmd}`);
    const output = `${r.stdout ?? ''}${r.stderr ?? ''}`.trim();
    const tail = output.split('\n').slice(-40).join('\n');
    if (tail) console.log(tail.replace(/^/gm, '  '));
    if (r.status === 127 || TOOL_MISSING.test(output)) {
      console.log(
        `  → this gate's tool seems not to be installed; install it or adjust gates.${name} in ${CONFIG}`,
      );
    }
  }
  const executed = names.length - skipped;
  console.log(
    `${executed - failed}/${executed} gates green (${phase})${skipped ? `; ${skipped} skipped` : ''}`,
  );
  return failed ? 1 : 0;
}

// ---------------------------------------------------------------- tokens

/** Above this share of the dev's monthly limit, a command asks for approval (core/tokens.md). */
export const TOKEN_ALERT = 0.2;
// Not text: an agent doesn't read it.
const NOT_TEXT =
  /\.(png|jpe?g|gif|ico|webp|pdf|zip|gz|woff2?|ttf|eot|exe|dll|so|dylib|bin)$|(^|\/)(package-lock\.json|pnpm-lock\.yaml|yarn\.lock)$|^\.aquila\//i;

/**
 * Tokens an agent spends reading the versioned files in `paths` (everything, if empty).
 * ponytail: ~4 chars per token × 2 (re-reads, output, tools) — rough estimate; tune the multiplier
 * against real measured usage.
 */
export function estimateTokens(paths = []) {
  const files = git('ls-files', '-z', '--', ...paths)
    .split('\0')
    .filter((f) => f && !NOT_TEXT.test(f) && existsSync(p(f)) && statSync(p(f)).isFile());
  const bytes = files.reduce((sum, f) => sum + statSync(p(f)).size, 0);
  return { files: files.length, tokens: Math.round((bytes / 4) * 2) };
}

const tokenLimit = () => (existsSync(p(LOCAL)) ? readJson(LOCAL).tokenLimit : null) ?? null;

export function tokens(args) {
  const { files, tokens: n } = estimateTokens(args.filter((a) => !a.startsWith('--')));
  const limit = tokenLimit();
  const share = limit ? n / limit : 0;
  const of = limit
    ? ` = ${(share * 100).toFixed(1)}% of the monthly limit (${limit})`
    : ' · no monthly limit set: no alert';
  console.log(`~${n} estimated tokens (${files} files)${of}`);
  if (share > TOKEN_ALERT)
    console.log(
      `! ALERT: above ${TOKEN_ALERT * 100}% of the monthly limit — ask the dev for approval before continuing (or narrow the scope)`,
    );
  return 0;
}

// ---------------------------------------------------------------- init / doctor

/** `.aquila/` is per project: one aquila package per project root, never overwriting another one's method. */
export function assertOwnMethod(root = ROOT) {
  const readme = join(root, METHOD, 'README.md');
  if (!existsSync(readme)) return;
  const owner = /^# \.aquila — (\S+) /.exec(readFileSync(readme, 'utf8'))?.[1];
  if (owner && owner !== NAME)
    throw new Error(
      `${METHOD}/ belongs to ${owner}: one aquila package per project root — ${NAME} would overwrite its method, routers and gates`,
    );
}

export function init(opts = {}) {
  assertOwnMethod();
  const done = [];
  const configured = existsSync(p(CONFIG));
  const existingConfig = configured ? assertConfig(loadConfig()) : null;
  if (!configured) {
    const preset = detectStack(ROOT);
    if (!preset.detected)
      done.push(`! ${PROFILE.framework} not found in package.json — ${NAME} targets ${PROFILE.stack} projects`);
    const notes = [];
    const cfg = defaultConfig(ROOT, preset, opts, {
      budgets: DEFAULT_BUDGETS,
      configPaths: DEFAULT_CONFIG_PATHS,
      notes,
    });
    mkdirSync(p('docs/ai'), { recursive: true });
    writeFileSync(p(CONFIG), `${JSON.stringify(cfg, null, 2)}\n`);
    done.push(`✓ ${CONFIG} (stack ${preset.name}; confirm the gates)`, ...notes);
  } else if (opts.lang || opts.codeLang || opts.tools || opts.mode || opts.lint || opts.prMaxFiles) {
    // Re-running init with the dev's answers updates the existing config.
    const cfg = existingConfig;
    if (opts.lang) cfg.language = { ...cfg.language, docs: opts.lang, answers: opts.lang };
    if (opts.codeLang) cfg.language = { ...cfg.language, code: opts.codeLang };
    if (opts.tools) cfg.tools = opts.tools;
    if (opts.mode) cfg.mode = opts.mode;
    if (opts.lint) cfg.lint = { ...cfg.lint, level: opts.lint };
    if (opts.prMaxFiles) cfg.review = { ...cfg.review, prMaxFiles: opts.prMaxFiles };
    writeFileSync(p(CONFIG), `${JSON.stringify(cfg, null, 2)}\n`);
    done.push(
      `✓ ${CONFIG} updated (language, tools, mode, lint ${cfg.lint?.level} and PR ≤ ${prMaxFiles(cfg)} files)`,
    );
  }
  if ('tokenLimit' in opts) {
    writeFileSync(p(LOCAL), `${JSON.stringify({ tokenLimit: opts.tokenLimit }, null, 2)}\n`);
    const what = opts.tokenLimit
      ? `monthly limit ${opts.tokenLimit} tokens`
      : 'no limit — no usage alert';
    done.push(`✓ ${LOCAL} (outside git): ${what}`);
  }
  const missing = INIT_FLAGS.filter(([, key]) => !(key in opts)).map(([flag]) => flag);
  if (missing.length)
    done.push(
      configured
        ? `ℹ without --${missing.join(', --')}: existing values kept`
        : `! without --${missing.join(', --')}: defaults used — ask the dev and repeat`,
    );
  // Doc indexes in the docs language (pt-BR/pt-PT translations), the English ones for the rest.
  const lang = loadConfig().language?.docs;
  const templates = join(PKG, 'templates');
  const copyMissing = (from, to) => {
    if (!existsSync(from)) return;
    for (const name of readdirSync(from)) {
      const src = join(from, name);
      const dest = join(to, name);
      if (statSync(src).isDirectory()) copyMissing(src, dest);
      else if (!existsSync(p(dest))) {
        mkdirSync(dirname(p(dest)), { recursive: true });
        cpSync(src, p(dest));
        done.push(`✓ ${posix(dest)}`);
      }
    }
  };
  if (lang && lang !== 'en') copyMissing(join(templates, 'i18n', lang, 'docs'), 'docs');
  copyMissing(join(templates, 'docs'), 'docs');
  copyMissing(join(templates, 'github'), '.github');
  // The CI caller is an adapter: sync writes it (only when package.json declares the package).
  if (!isInstalled())
    done.push(`! ${NAME} is not in package.json: no CI workflow and hooks may break → npm i -D ${NAME}`);
  done.push(...sync());
  done.push(...installHooks(opts));
  if (REPO.prefix)
    done.push(
      `ℹ project in subfolder ${REPO.prefix} of the git repository: hooks, CI workflow, git exclude and Copilot instructions are written at the repository root`,
    );
  if (opts.install) done.push(...installLintPlugins());
  const cfg = loadConfig();
  done.push(
    cfg.mode === 'team'
      ? 'ℹ team mode: commit the managed routers, `/aquila-*` commands and settings; each dev still sets the hooks with init'
      : 'ℹ local mode: generated routers and settings are local; each dev runs init; cloud agents need team',
  );
  if (!(cfg.hooks?.ci ?? []).length)
    done.push(`! no CI gates detected — define them in ${CONFIG} → gates and hooks.ci`);
  if (!testGate(cfg))
    done.push(
      `! no test gate (no test/test:ci/coverage script): "done" will not run any test — add a test script and gates.test in ${CONFIG}`,
    );
  if (cfg.lint?.pending)
    done.push(
      `! lint-aquila left out of the gates until the engine is installed: ${cfg.lint.pending} — after installing run \`npx ${NAME} sync\``,
    );
  const plugins = missingLintPlugins(ROOT, cfg.lint?.level ?? 'off');
  if (plugins.length && !opts.install)
    done.push(`! lint ${cfg.lint.level}: plugins missing — npm i -D ${plugins.join(' ')} (or init --install)`);
  done.push(`ℹ ${lintSummary(cfg.lint?.level ?? 'off', cfg.lint?.engine ?? null, ROOT)}`);

  console.log(done.join('\n'));
  console.log(
    `\nCLI: technical install and templates; /aquila-init completes the setup with /aquila-docs (CONTEXT, golden, instructions, C4), CI/hooks integration and validation. Resolve the warnings before starting a plan. Validate this machine with \`npx ${NAME} check --ready\` and run \`npx ${NAME} gate ci\`.`,
  );
  return 0;
}

/** Some gate runs tests (the definition of done means nothing without one). */
const testGate = (cfg) =>
  Object.keys(cfg.gates ?? {}).some((name) => /^(?:test|tests|unit|coverage)(?:[:-].*)?$/.test(name));

/** `init --install`: installs the lint plugins the level needs, with versions that fit each other. */
function installLintPlugins() {
  const cfg = loadConfig();
  const plugins = missingLintPlugins(ROOT, cfg.lint?.level ?? 'off');
  if (!plugins.length) return [];
  const cmd = `npm i -D ${plugins.join(' ')}`;
  const r = spawnSync(cmd, { cwd: ROOT, shell: true, encoding: 'utf8', stdio: 'inherit' });
  if (r.status !== 0) return [`✗ ${cmd} failed — run it by hand`];
  const notes = [`✓ ${cmd}`];
  notes.push(...sync());
  return notes;
}

/** How to call the dispatcher from another hook manager (from any folder of the repository). */
const dispatchCall = () =>
  `\`"$(git rev-parse --show-toplevel)/${DISPATCH_DIR}/pre-commit"\` and \`"$(git rev-parse --show-toplevel)/${DISPATCH_DIR}/pre-push" "$@"\``;

/**
 * core.hooksPath → the shared dispatcher. One hooksPath per repository, resolved by git from the root, so
 * it works for every project in it. A pre-0.2.0 aquila path, or a custom folder that is gone or has no hooks
 * (nothing runs there), moves to the dispatcher; another manager with hooks stays unless --hooks=dispatcher.
 */
function installHooks(opts = {}) {
  if (!REPO.git) return ['! no git repository: git hooks not set'];
  const hooksPath = git('config', '--get', 'core.hooksPath');
  const kind = hooksPathKind(REPO.top, hooksPath);
  // Hooks already in .git/hooks (lefthook, pre-commit, hand-written) would stop running if core.hooksPath
  // pointed elsewhere: in that case don't set it and say how to integrate.
  const hooksDir = resolve(ROOT, git('rev-parse', '--git-path', 'hooks'));
  const existing = existsSync(hooksDir)
    ? readdirSync(hooksDir).filter((n) => !n.endsWith('.sample'))
    : [];
  const set = (why) => {
    git('config', 'core.hooksPath', DISPATCH_DIR);
    return `✓ git config core.hooksPath = ${DISPATCH_DIR}${why} (shared dispatcher at the repository root)`;
  };
  if (kind === 'dispatcher') return [];
  if (kind === 'none' && existing.length && opts.hooks !== 'dispatcher')
    return [
      `! git hooks already exist in .git/hooks (${existing.join(', ')}) — not replaced; call ${dispatchCall()} from them (or init --hooks=dispatcher)`,
    ];
  if (kind === 'none') return [set('')];
  if (kind === 'legacy') return [set(` (was ${hooksPath}, the pre-0.2.0 layout)`)];
  if (kind === 'missing')
    return [set(` (was ${hooksPath}: that folder is gone or has no pre-commit/pre-push, so nothing ran)`)];
  // kind === 'manager'
  if (opts.hooks === 'dispatcher')
    return [set(` (was ${hooksPath}; its hooks no longer run — move what you need into a project gate)`)];
  return [
    `! a hook manager already exists (${hooksPath}) — kept; call ${dispatchCall()} from it, or migrate with init --hooks=dispatcher`,
  ];
}

/** Installs the plugin on this machine only (.claude/settings.local.json; the versioned settings stay as they are). */
const pluginInstall = () =>
  `cd "${ROOT}" && claude plugin marketplace add ./.aquila && claude plugin install aquila@${NAME} --scope local`;

function claudePluginInstalled() {
  // On Windows `claude` is a .cmd and needs the shell; command as a single string (DEP0190).
  const r = spawnSync('claude plugin list', { encoding: 'utf8', shell: true, timeout: 15000 });
  // Not found / timed out / failed: unknown, never "missing".
  if (r.error || r.status !== 0 || !r.stdout) return null;
  return r.stdout.includes(`aquila@${NAME}`);
}

/** The project's own ESLint without aquilaEslintCompat(): aquila-only disables break it or are removed by --fix. */
function compatHints(cfg) {
  if ((cfg.lint?.level ?? 'off') === 'off' || cfg.lint?.engine !== 'eslint') return [];
  const file = ['js', 'mjs', 'cjs', 'ts', 'mts', 'cts'].map((x) => `eslint.config.${x}`).find((f) => existsSync(p(f)));
  if (!file || read(file).includes('aquilaEslintCompat')) return [];
  return [
    `! ${file} does not include aquilaEslintCompat(): an eslint-disable for a rule only ${NAME} lint runs fails there ("Definition for rule … was not found") or is removed by --fix → import { aquilaEslintCompat } from '${NAME}/lint/eslint/compat.mjs' and add aquilaEslintCompat() as the last item of the exported array`,
  ];
}

const PHASES = ['pre-commit', 'pre-push'];

/** Gates that never run or run twice, and hooks from another manager that don't go through the dispatcher. */
function gateWarnings(cfg, hooksPath) {
  const out = [];
  const ci = cfg.hooks?.ci ?? Object.keys(cfg.gates ?? {});
  // done.gates runs too: the agent runs it before saying done (e.g. tests that only the project's own CI runs).
  const phased = new Set([...ci, ...(cfg.done?.gates ?? []), ...PHASES.flatMap((ph) => cfg.hooks?.[ph] ?? [])]);
  for (const name of Object.keys(cfg.gates ?? {}).filter((n) => !phased.has(n)))
    out.push(
      `! gate ${name} in no phase (hooks.pre-commit/pre-push/ci, done.gates): never runs${name === 'lint-aquila' ? ` — on legacy code use \`npx ${NAME} lint --baseline\` instead of leaving it out` : ''}`,
    );
  // The coverage command runs the suite: with both, CI runs every test twice.
  if (ci.includes('test') && ci.includes('coverage') && coverageRunsTests(ROOT, cfg.gates ?? {}))
    out.push('! hooks.ci has test and coverage, and the coverage script is the test command with coverage: CI runs the suite twice — remove test from hooks.ci (keep it in done.gates if you want it listed)');
  if (hooksPathKind(REPO.top, hooksPath) !== 'manager') return out;
  // husky v9 sets `.husky/_` (generated wrappers); the project's scripts are in `.husky/`.
  // A relative hooksPath is resolved by git from the repository root.
  const dir = hooksPath.replace(/[\\/]_[\\/]?$/, '');
  for (const phase of PHASES) {
    const file = resolve(REPO.top, dir, phase);
    if (!existsSync(file)) continue;
    if (!/(?:aquila\.mjs|aquila[\w-]*)\s+gate|\.aquila-hooks\//.test(readFileSync(file, 'utf8')))
      out.push(
        `! ${posix(join(dir, phase))} does not call the aquila dispatcher: hooks.${phase} from ${CONFIG} never runs → call ${dispatchCall()}`,
      );
  }
  return out;
}

/** The package's CLI as the dispatcher finds it: <project>/node_modules, then hoisted up to the root. */
function hookBin() {
  const rel = `node_modules/${NAME}/bin/aquila.mjs`;
  for (let dir = REPO.dir; ; dir = posix(dirname(dir))) {
    if (existsSync(join(REPO.top, dir, rel))) return dir === '.' ? rel : `${dir}/${rel}`;
    if (dir === '.') return null;
  }
}

/**
 * Hooks and CI that git/GitHub would never run: a 0.1.0 layout, a core.hooksPath with no hooks, the project
 * missing from the dispatcher registry, hooks versioned without +x. Fails `check`.
 */
function locationIssues(cfg) {
  const issues = [];
  if (REPO.prefix && isGenerated(LEGACY_CI))
    issues.push(
      `${REPO.prefix}${LEGACY_CI}: GitHub only runs workflows from the repository root → npx ${NAME} sync writes ${posix(relative(REPO.top, p(CI_CALLER)))}`,
    );
  if (!wantsWorkflow(cfg) && isGenerated(CI_CALLER))
    issues.push(`${posix(relative(REPO.top, p(CI_CALLER)))}: ci.workflow is false → npx ${NAME} sync removes it`);
  if (!REPO.git) return issues;
  // Checked in CI too (no hooksPath there): the index is what Linux/macOS clones get.
  issues.push(...indexModeIssues(REPO.top).map((i) => i.replace('<package>', NAME)));
  const hooksPath = git('config', '--get', 'core.hooksPath');
  const kind = hooksPathKind(REPO.top, hooksPath);
  if (kind === 'legacy')
    issues.push(`core.hooksPath ${hooksPath}: pre-0.2.0 hook layout (git resolves it from the repository root) → npx ${NAME} init`);
  else if (kind === 'missing')
    issues.push(`core.hooksPath ${hooksPath}: no pre-commit/pre-push there, nothing runs → npx ${NAME} init`);
  else if (kind === 'dispatcher') {
    for (const phase of HOOK_PHASES) {
      const file = join(REPO.top, DISPATCH_DIR, phase);
      if (!existsSync(file)) issues.push(`${DISPATCH_DIR}/${phase} missing → npx ${NAME} init`);
      else if (!isDispatcher(readFileSync(file, 'utf8')))
        issues.push(`${DISPATCH_DIR}/${phase} is not the aquila dispatcher → review it or npx ${NAME} init`);
    }
    if (!readRegistry(REPO.top).some((e) => e.pkg === NAME && e.dir === REPO.dir))
      issues.push(`${REPO.dir} is not in ${REGISTRY}: the hook dispatcher skips this project → npx ${NAME} init`);
  }
  return issues;
}

/** Doctor lines for hooks, CI workflow and the other aquila projects in the repository. */
function repoDiagnostics(cfg, hooksPath) {
  if (REPO.prefix)
    console.log(
      `ℹ project in subfolder ${REPO.prefix} of the git repository — hooks, CI and Copilot instructions (.github/instructions/aquila-${ciSlug(REPO.prefix)}.instructions.md, and per-folder rules as .github/instructions/${ciSlug(REPO.prefix)}-<area>.instructions.md with applyTo '${REPO.prefix}…') live at the root`,
    );
  const kind = hooksPathKind(REPO.top, hooksPath);
  if (kind === 'dispatcher') {
    const problems = [];
    for (const phase of HOOK_PHASES) {
      const file = join(REPO.top, DISPATCH_DIR, phase);
      if (!existsSync(file)) problems.push(`${phase} missing`);
      else if (!isDispatcher(readFileSync(file, 'utf8'))) problems.push(`${phase} is not the aquila dispatcher`);
      else if (process.platform !== 'win32' && !(statSync(file).mode & 0o111))
        problems.push(`${phase} not executable`);
    }
    if (!readRegistry(REPO.top).some((e) => e.pkg === NAME && e.dir === REPO.dir))
      problems.push(`${REPO.dir} not in ${REGISTRY}`);
    const bin = hookBin();
    if (!bin) problems.push(`node_modules/${NAME} not found from ${REPO.dir} → npm install`);
    log(
      !problems.length,
      `git hooks: ${DISPATCH_DIR} (${problems.length ? `${problems.join('; ')} → npx ${NAME} init` : `dispatcher; this project registered; hook finds ${bin}`})`,
    );
  } else {
    log(kind === 'manager', `git hooks: ${hooksPath || `none → npx ${NAME} init`}`);
  }
  if (isInstalled() && !wantsWorkflow(cfg)) {
    console.log(`ℹ ci.workflow false — your pipeline must run (in ${REPO.dir}):\n${ciSnippet().replace(/^/gm, '    ')}`);
  } else if (isInstalled()) {
    const ci = posix(relative(REPO.top, p(CI_CALLER)));
    log(existsSync(p(CI_CALLER)), `CI workflow: ${ci}${existsSync(p(CI_CALLER)) ? '' : ` missing → npx ${NAME} sync (or ci.workflow: false)`}`);
  }
  for (const issue of locationIssues(cfg)) log(false, issue);
  const projects = readRegistry(REPO.top);
  if (projects.length > 1) {
    console.log(
      `ℹ ${projects.length} aquila projects share ${DISPATCH_DIR}: ${projects.map((e) => `${e.pkg} ${e.dir}`).join(', ')}`,
    );
    // Each project's Claude Code plugin is enabled in its own .claude/settings.json.
    if (cfg.tools.includes('claude'))
      console.log(
        `ℹ Claude Code: open the session in ${REPO.dir}/ to load aquila@${NAME} (at the repository root no project's plugin is enabled)`,
      );
  }
}

export function doctor() {
  log(true, `${NAME} ${version()}`);
  if (!existsSync(p(CONFIG))) {
    log(false, `${CONFIG} missing → npx ${NAME} init`);
    return 0;
  }
  const cfg = loadConfig();
  const { errors } = configValidation(cfg);
  if (errors.length) {
    log(false, `${CONFIG} invalid (schema: .aquila/schema/aquila.schema.json):\n  ${errors.join('\n  ')}`);
    return 1;
  }
  log(
    true,
    `mode ${cfg.mode} · tools ${cfg.tools.join(', ')} · stack ${cfg.stack} · lint ${cfg.lint?.level ?? 'off'}${cfg.lint?.engine ? ` (${cfg.lint.engine})` : ''}`,
  );
  console.log(`ℹ ${lintSummary(cfg.lint?.level ?? 'off', cfg.lint?.engine ?? null, ROOT)}`);
  for (const issue of lintPeerIssues(ROOT, cfg.lint?.level ?? 'off')) log(false, issue);
  log(isInstalled(), isInstalled() ? `${NAME} in package.json` : `${NAME} not in package.json → npm i -D ${NAME}`);
  const limit = tokenLimit();
  console.log(
    limit
      ? `✓ monthly token limit ${limit} (alert above ${TOKEN_ALERT * 100}% per command)`
      : `! no monthly token limit in ${LOCAL}: no usage alert → /aquila-config`,
  );
  const context = existsSync(p('docs/ai/CONTEXT.md')) ? read('docs/ai/CONTEXT.md') : '';
  const filled = context && !context.includes(TEMPLATE_MARKS['docs/ai/CONTEXT.md']);
  log(
    filled,
    filled ? 'docs/ai/CONTEXT.md filled in' : 'docs/ai/CONTEXT.md still to fill in → /aquila-docs',
  );
  const missing = [
    ...plan(cfg)
      .filter((i) => !existsSync(p(i.path)))
      .map((i) => i.path),
    ...settingsDrift(cfg),
  ];
  log(
    !missing.length,
    `adapters${missing.length ? ` missing: ${missing.join(', ')} → npx ${NAME} sync` : ''}`,
  );
  if (!testGate(cfg)) log(false, `no test gate: "done" runs no test → add gates.test in ${CONFIG}`);
  const hooksPath = git('config', '--get', 'core.hooksPath');
  repoDiagnostics(cfg, hooksPath);
  for (const warning of gateWarnings(cfg, hooksPath)) console.log(warning);
  for (const hint of compatHints(cfg)) console.log(hint);
  if (cfg.tools.includes('claude')) {
    // Team mode: .claude/settings.json (versioned, written by sync) already enables it, so Claude Code offers it
    // when the folder is opened and trusted. Installing by hand uses --scope local: --scope project rewrites
    // that versioned file (only its key order changes, a diff with no real change).
    const team = cfg.mode === 'team' && !settingsDrift(cfg).some((d) => d.startsWith('.claude/'));
    if (team) console.log(`ℹ aquila@${NAME} enabled in .claude/settings.json (team): Claude Code offers it when this folder is opened`);
    const installed = claudePluginInstalled();
    if (installed === null)
      console.log('! claude CLI unavailable or failed — Claude Code plugin not verified');
    else
      log(
        installed,
        installed
          ? `Claude Code plugin aquila@${NAME}`
          : `Claude Code plugin missing → ${pluginInstall()}`,
      );
  }
  return 0;
}

// ---------------------------------------------------------------- main

/** init flags in the order of the `/aquila-init` questions → key in opts. */
const INIT_FLAGS = [
  ['lang', 'lang'],
  ['tools', 'tools'],
  ['token-limit', 'tokenLimit'],
  ['mode', 'mode'],
  ['lint', 'lint'],
  ['pr-max-files', 'prMaxFiles'],
];
/** init flags that are not questions (detected or opt-in). */
const EXTRA_INIT_FLAGS = [
  ['code-lang', 'codeLang'],
  ['hooks', 'hooks'],
  ['install', 'install'],
];
export const LANGUAGES = ['en', 'pt-BR', 'pt-PT'];

export function parseOpts(args) {
  const allowedTools = ['copilot', 'claude', 'codex'];
  const flags = [...INIT_FLAGS, ...EXTRA_INIT_FLAGS];
  const opts = {};
  for (const arg of args) {
    const [k, ...rest] = arg.replace(/^--/, '').split('=');
    const v = rest.join('=');
    if (!flags.some(([flag]) => flag === k))
      throw new Error(`unknown flag: ${arg} (valid: ${flags.map(([f]) => `--${f}`).join(' ')})`);
    if (k === 'install') {
      if (v) throw new Error('--install takes no value');
      opts.install = true;
      continue;
    }
    if (!v) throw new Error(`--${k} needs a value (--${k}=…)`);
    if (k === 'lang' || k === 'code-lang') {
      if (!LANGUAGES.includes(v)) throw new Error(`--${k} is ${LANGUAGES.join(', ')}`);
      opts[k === 'lang' ? 'lang' : 'codeLang'] = v;
    }
    if (k === 'hooks') {
      if (v !== 'dispatcher') throw new Error('--hooks is dispatcher (moves core.hooksPath to .aquila-hooks)');
      opts.hooks = v;
    }
    if (k === 'token-limit') {
      opts.tokenLimit = v === 'none' ? null : Number(v);
      if (opts.tokenLimit !== null && (!Number.isFinite(opts.tokenLimit) || opts.tokenLimit <= 0))
        throw new Error('--token-limit is a number of tokens > 0 or none');
    }
    if (k === 'tools') {
      const tools = v.split(',');
      if (
        tools.some((tool) => !allowedTools.includes(tool)) ||
        new Set(tools).size !== tools.length
      ) {
        throw new Error(`--tools accepts unique tools: ${allowedTools.join(', ')}`);
      }
      opts.tools = tools;
    }
    if (k === 'mode') {
      if (!['local', 'team'].includes(v)) throw new Error('--mode is local or team');
      opts.mode = v;
    }
    if (k === 'lint') {
      if (!['off', 'standard', 'high'].includes(v))
        throw new Error('--lint is off, standard or high');
      opts.lint = v;
    }
    if (k === 'pr-max-files') {
      opts.prMaxFiles = Number(v);
      if (!Number.isInteger(opts.prMaxFiles) || opts.prMaxFiles < 1)
        throw new Error('--pr-max-files is an integer number of files > 0');
    }
  }
  return opts;
}

export function nodeVersionSupported(v = process.versions.node) {
  const major = Number.parseInt(v.split('.')[0], 10);
  return Number.isInteger(major) && major >= 22;
}

export { globToRegex, LINT_LEVELS, lintRules, validate };

/** `npx <package> <command> --help`: each command with its flags. */
export const HELP = {
  init: `npx ${NAME} init [flags] — detects the project, writes docs/ai/aquila.json and docs/, generates adapters, sets the hooks
  --lang=en|pt-BR|pt-PT        language of docs and answers (doc templates in that language)
  --code-lang=en|pt-BR|pt-PT   language of identifiers (default: detected from the source)
  --tools=copilot,claude,codex agents to generate adapters for
  --token-limit=<n>|none       the dev's monthly token limit (docs/ai/aquila.local.json, outside git)
  --mode=local|team            local: adapters per machine; team: routers and settings versioned
  --lint=off|standard|high     lint level (lint-aquila gate)
  --pr-max-files=<n>           changed files per PR before proposing a split (default 30)
  --hooks=dispatcher           move an existing core.hooksPath (husky…) to the shared .aquila-hooks dispatcher
  --install                    install the lint plugins the level needs (npm i -D …)`,
  sync: `npx ${NAME} sync — regenerates .aquila/, adapters, CI workflow and the hook dispatcher from docs/ai/aquila.json`,
  check: `npx ${NAME} check [--ready] [--verbose] — links, budgets, adapters in sync, hooks/CI location (fails in CI)
  --ready     also verifies this machine (hooks, plugin, docs filled in); does not run gates
  --verbose   lists every file without per-folder instructions`,
  doctor: `npx ${NAME} doctor — installation diagnostics (never fails): config, lint plugins, hooks, CI, plugin`,
  gate: `npx ${NAME} gate <pre-commit|pre-push|ci> — runs that phase's gates from docs/ai/aquila.json (prints failures)`,
  lint: `npx ${NAME} lint [rules|matrix] [--level=off|standard|high] [--fix] [--baseline] — the lint-aquila gate
  rules       rules of the level and their local state       matrix   catalog → ESLint plugins
  --fix       apply ESLint fixes                              --baseline record the current violations (docs/ai/lint-baseline.json): only new ones fail`,
  tokens: `npx ${NAME} tokens [paths…] — estimated tokens to read those versioned files (alert above 20% of the monthly limit)`,
};

const USAGE = `usage: npx ${NAME} <command> (npx ${NAME} <command> --help for its flags)
  init [--lang=en|pt-BR|pt-PT] [--code-lang=en|pt-BR|pt-PT] [--tools=copilot,claude,codex] [--token-limit=<n>|none] [--mode=local|team] [--lint=off|standard|high] [--pr-max-files=<n>] [--hooks=dispatcher] [--install]
  sync | check [--ready] [--verbose] | doctor | gate <pre-commit|pre-push|ci>
  lint [rules|matrix] [--level=off|standard|high] [--fix] [--baseline] | tokens [paths…] | --version`;

const isMain = process.argv[1] && realpathSync(process.argv[1]) === realpathSync(SELF);
if (isMain) {
  if (!nodeVersionSupported()) {
    console.error(`✗ ${NAME} requires Node ≥ 22; current version: ${process.versions.node}`);
    process.exit(1);
  }
  const [cmd, ...args] = process.argv.slice(2);
  const commands = {
    init: () => init(parseOpts(args)),
    sync: () => (console.log(sync().join('\n') || '✓ adapters already in sync'), 0),
    check: () => check(args),
    doctor,
    gate: () => {
      if (args.length > 1) throw new Error('gate arguments: accepts a single phase');
      return gate(args[0] ?? 'ci');
    },
    tokens: () => tokens(args),
    lint: () => lint(args),
    '--version': () => (console.log(version()), 0),
  };
  if (!commands[cmd]) {
    console.log(USAGE);
    process.exit(cmd && !['help', '--help', '-h'].includes(cmd) ? 1 : 0);
  }
  if (args.includes('--help') || args.includes('-h')) {
    console.log(HELP[cmd] ?? USAGE);
    process.exit(0);
  }
  try {
    process.exit(await commands[cmd]());
  } catch (error) {
    console.error(`✗ ${error.message}`);
    process.exit(1);
  }
}
